sql.if:
AND EXISTS (
  SELECT 1
  FROM class_schedule filtered_schedule
  
    JOIN location filtered_location ON filtered_location.id=filtered_schedule.location_id
  
  WHERE filtered_schedule.offering_id=o.id
  
    AND EXISTS (
      SELECT 1
      FROM schedule_teacher filtered_schedule_teacher
      JOIN teacher filtered_teacher ON filtered_teacher.id=filtered_schedule_teacher.teacher_id
      WHERE filtered_schedule_teacher.schedule_id=filtered_schedule.id
        AND LOCATE(LOWER(#{criteria.teacherName}), LOWER(filtered_teacher.normalized_name)) > 0
    )
  
  
    AND EXISTS (
      SELECT 1
      FROM schedule_week filtered_week
      WHERE filtered_week.schedule_id=filtered_schedule.id
        AND filtered_week.week_no=#{criteria.week}
    )
  
  AND filtered_schedule.weekday=#{criteria.weekday}
  
    AND filtered_schedule.start_section <=#{criteria.section}
    AND filtered_schedule.end_section >=#{criteria.section}
  
  
    AND LOCATE(LOWER(#{criteria.location}), LOWER(filtered_location.normalized_name)) > 0
  
)

mapper.select:
SELECT o.id,o.display_name AS displayName FROM course_offering o WHERE () AND o.id=#{id} AND o.source_scope_college_id=#{sourceCollegeId}
AND EXISTS (SELECT 1 FROM class_schedule filtered_schedule JOIN schedule_teacher filtered_teacher ON filtered_teacher.schedule_id=filtered_schedule.id WHERE filtered_schedule.offering_id=o.id AND filtered_teacher.teacher_id=#{teacherId})
ORDER BY o.id

SELECT schedule.offering_id AS offeringId, schedule.id AS scheduleId, schedule.weekday, schedule.start_section AS startSection, schedule.end_section AS endSection, schedule.raw_week_text AS rawWeekText, location.id AS locationId, location.display_name AS locationDisplayName, location.location_group AS locationGroup, location.location_type AS locationType FROM class_schedule schedule JOIN location ON location.id=schedule.location_id WHERE schedule.offering_id IN
#{offeringId}
ORDER BY schedule.offering_id ASC, schedule.weekday ASC, schedule.start_section ASC, schedule.end_section ASC, schedule.id ASC

SELECT schedule_id AS scheduleId, week_no AS weekNo FROM schedule_week WHERE schedule_id IN
#{scheduleId}
GROUP BY schedule_id, week_no ORDER BY schedule_id ASC, week_no ASC

SELECT relation.schedule_id AS scheduleId, teacher.id AS teacherId, teacher.display_name AS displayName FROM schedule_teacher relation JOIN teacher ON teacher.id=relation.teacher_id WHERE relation.schedule_id IN
#{scheduleId}
GROUP BY relation.schedule_id, teacher.id, teacher.display_name ORDER BY relation.schedule_id ASC, teacher.display_name ASC, teacher.id ASC

SELECT DISTINCT teacher.id AS teacherId, teacher.display_name AS displayName FROM course_offering o JOIN class_schedule schedule ON schedule.offering_id=o.id JOIN schedule_teacher relation ON relation.schedule_id=schedule.id JOIN teacher ON teacher.id=relation.teacher_id WHERE () AND teacher.id IN
#{teacherId}
ORDER BY teacher.id ASC

SELECT DISTINCT relation.teacher_id AS selectedTeacherId, o.id AS offeringId, o.display_name AS displayName, o.activity_type AS activityType, o.class_group_text AS classGroupText, o.student_count AS studentCount, sem.id AS semesterId, sem.semester_code AS semesterCode, sem.semester_name AS semesterName, c.syllabus_ref AS syllabusRef, c.description AS description FROM course_offering o JOIN semester sem ON sem.id=o.semester_id LEFT JOIN course c ON c.id=o.course_id JOIN class_schedule participating_schedule ON participating_schedule.offering_id=o.id JOIN schedule_teacher relation ON relation.schedule_id=participating_schedule.id WHERE () AND relation.teacher_id IN
#{teacherId}
ORDER BY relation.teacher_id ASC, o.display_name ASC, o.id ASC

SELECT relation.teacher_id AS selectedTeacherId, o.id AS offeringId, schedule.id AS scheduleId, schedule.weekday, schedule.start_section AS startSection, schedule.end_section AS endSection, schedule.raw_week_text AS rawWeekText, location.id AS locationId, location.display_name AS locationDisplayName, location.location_group AS locationGroup, location.location_type AS locationType FROM course_offering o JOIN class_schedule schedule ON schedule.offering_id=o.id JOIN schedule_teacher relation ON relation.schedule_id=schedule.id JOIN location ON location.id=schedule.location_id WHERE () AND relation.teacher_id IN
#{teacherId}
ORDER BY relation.teacher_id ASC, o.id ASC, schedule.weekday ASC, schedule.start_section ASC, schedule.end_section ASC, schedule.id ASC
